import { Accessor, createSignal, Setter } from "solid-js";

import { Catalog } from "#core/ui/utilities/utility-serialize.js";

declare global {
	/**
	 * Lenses need to define a new entry for each lens
	 *
	 * Example: 'fxs-default-layer' : DefaultLens
	 *
	 * !DON'T FORGET to also include the reference in index.d.ts!
	 * */
	interface LensTypeMap {}
}

// Alias for LensLayerTypeMap key
export type LensName = keyof LensTypeMap extends never ? string : keyof LensTypeMap;

export interface ILens {
	/** Type enum for the layers this lens activates */
	activeLayers: Set<LensLayerName>;

	/** Type enum for the layers this lens allows to be enabled while it's active */
	allowedLayers: Set<LensLayerName>;

	/** Flag whether to skip caching enabled layers, in cases where this may be different from active layers. */
	skipCachingEnabledLayers?: boolean;

	/**
	 * Flag whether or not to blend enabled layers when transitioning from one lens to another.
	 * If undefined, assume blending.
	 */
	blendEnabledLayersOnTransition?: boolean;

	/** Stores the layers that were enabled last time this lens was active so we can enable those layers again */
	lastEnabledLayers?: Set<LensLayerName>;

	/** Stores the player id that has the last enabled layers. */
	lastEnabledLayersPlayerID?: PlayerId;

	/** If a 2D UI piece will exist as a legend or key of what the lens describes.  */
	hasLegend?: boolean;

	/** If true, this lens will query the user config settings. Likely only default-lens.ts */
	useUserConfig?: boolean;
}

declare global {
	/**
	 * Lens layers need to define a new entry for each layer
	 *
	 * Example: 'fxs-hexgrid-layer' : HexGridLensLayer
	 *
	 * !DON'T FORGET to also include the reference in globals.d.ts!
	 * */
	interface LensLayerTypeMap {}
}

// Alias for LensLayerTypeMap key
export type LensLayerName = keyof LensLayerTypeMap;

export interface ILensLayer {
	/** Called when a layer is first registered */
	initLayer(): void;

	/** Called when a layer is applied */
	applyLayer(): void;

	/** Called when a layer is removed */
	removeLayer(): void;

	/** Called if present to determine the option name of a lens layer */
	getOptionName?(): string;
}

export const LensLayerEnabledEventName = "lens-event-layer-enabled" as const;
export const LensLayerDisabledEventName = "lens-event-layer-disabled" as const;
type LensLayerEventName = typeof LensLayerEnabledEventName | typeof LensLayerDisabledEventName;

/**
 * LensLayerEvent is fired when a lens layer is enabled or disabled
 */
export class LensLayerEvent extends CustomEvent<{ layer: LensLayerName }> {
	constructor(name: LensLayerEventName, layer: LensLayerName) {
		super(name, {
			bubbles: false,
			cancelable: false,
			detail: { layer },
		});
	}
}

export const LensActivationEventName = "lens-event-active-lens" as const;
export interface LensActivationEventDetail {
	prevLens: LensName | undefined;
	activeLens: LensName;
	hasLegend: boolean;
}
/**
 * LensActivationEvent is fired when a lens is activated
 */
export class LensActivationEvent extends CustomEvent<LensActivationEventDetail> {
	constructor(
		prevLens: LensActivationEventDetail["prevLens"],
		activeLens: LensActivationEventDetail["activeLens"],
		hasLegend: boolean,
	) {
		super(LensActivationEventName, {
			detail: {
				activeLens,
				prevLens,
				hasLegend,
			},
		});
	}
}

export interface LensToggleOptions {
	force?: boolean; // Forces on (true), off (false), or change from current state (undefined)
	serialize?: boolean; // Write the corresponding value to the User Config (across saves)
}

const LENS_CATALOG_VERSION = 1;
const LENS_CATALOG_NAME = "LensManagerCatalog";
const LENS_CATALOG_OBJECT_NAME = "tracked-lens";
const ENABLED_LAYERS_CATALOG_OBJECT_ID = "enabled";

class LensManagerSingleton {
	private catalogs: Catalog[] = [];
	private currentCatalog: Catalog;
	private playerID: PlayerId;

	private showDebugInfo = false;
	private lenses = new Map<LensName, ILens>();
	private layers = new Map<LensLayerName, ILensLayer>();

	private activeLensGetter: Accessor<LensName | undefined>;
	private activeLensSetter: Setter<LensName | undefined>;
	private get activeLens(): LensName | undefined {
		return this.activeLensGetter();
	}
	private set activeLens(value: LensName | undefined) {
		this.activeLensSetter(value);
	}

	constructor() {
		const [activeLensGetter, activeLensSetter] = createSignal<LensName | undefined>(undefined);
		this.activeLensGetter = activeLensGetter;
		this.activeLensSetter = activeLensSetter;

		this.playerID = GameContext.localPlayerID;

		this.currentCatalog = new Catalog({
			name: LENS_CATALOG_NAME,
			version: LENS_CATALOG_VERSION,
			player: Configuration.getGame().isHotseat ? Players.get(this.playerID) : null,
		});

		this.catalogs[this.playerID] = this.currentCatalog;

		if (Configuration.getGame().isHotseat) {
			engine.on("LocalPlayerChanged", this.onLocalPlayerChanged, this);
		}
	}

	private enabledLayers = new Set<LensLayerName>();

	registerLens(lensType: LensName, lens: ILens) {
		if (this.lenses.has(lensType)) {
			console.error(`lens-manager: Attempted to add duplicate lens type: ${lensType}`);
			return;
		}

		this.lenses.set(lensType, lens);
	}

	registerLensLayer(layerType: LensLayerName, layer: ILensLayer) {
		if (this.layers.has(layerType)) {
			console.error(`lens-manager: Attempted to add duplicate layer type: ${layerType}`);
			return;
		}

		layer.initLayer();

		this.layers.set(layerType, layer);

		// Check to see if our active lens was waiting for this layer to enable it
		// Mainly for 'fxs-default-lens' while all lenses and layers are getting loaded
		const lens = this.activeLens ? this.lenses.get(this.activeLens) : undefined;
		if (lens) {
			if (lens.activeLayers.has(layerType)) {
				this.enableLayer(layerType);
			}
		} else if (this.showDebugInfo) {
			console.log(`lens-manager: Failed to find '${this.activeLens}' during registerLensLayer.`);
		}

		// Check if this layer was previous on, and re-activate if so.
		if (this.getLayerOption(layerType) != layerType) {
			const enable = this.readTrackedLayer(layerType);
			const hasLayer = lens?.activeLayers.has(layerType);
			if (enable && !hasLayer) {
				this.enableLayer(layerType); // Should be enabled and is off, so turn on.
			} else if (!enable && hasLayer) {
				this.disableLayer(layerType); // Should be off but is on, so turn off.
			} else {
				// No change required.
			}
		}
	}

	getActiveLens() {
		if (this.activeLens === undefined) {
			console.error(`lens-manager: No active lens has been set yet`);
		}

		return this.activeLens as LensName;
	}

	setActiveLens(type: LensName): boolean {
		if (type === this.activeLens) {
			return true;
		}

		const lens = this.lenses.get(type);
		if (lens == undefined) {
			console.error(`lens-manager: Failed to find lens for type ${type}`);
			return false;
		}

		if (this.activeLens !== undefined) {
			const prevLens = this.lenses.get(this.activeLens);
			if (prevLens != undefined) {
				// Cache the enabled layers in the previous lens so we can transition back to those when we return
				if (!prevLens.skipCachingEnabledLayers) {
					//Only cache layers for lenses with this tag off
					prevLens.lastEnabledLayers = this.getEnabledLayers();
					prevLens.lastEnabledLayersPlayerID = this.playerID;
				}
			}
		} else {
			// Since no active lens, assume this is starting up and need to deserialize from user config.
			this.resetLayersFromSerialize();
		}

		// Set active lens
		const prevLensString = this.activeLens;
		this.activeLens = type;

		if (this.showDebugInfo) {
			console.info(`lens-manager: Leaving '${prevLensString}' lens.`);
			console.info(`lens-manager: Entering '${this.activeLens}' lens.`);
		}

		// Use previously enabled layers if available, otherwise use the default active layers
		const nextLensLayers =
			(lens.lastEnabledLayers && lens.lastEnabledLayersPlayerID == this.playerID
				? lens.lastEnabledLayers
				: undefined) ?? this.getActiveLayers(lens);
		const nextAllowedLayers = lens.allowedLayers;

		// Blend layers (persisting enabled layers if they exist in the `allowedLayers` set) unless explicitly disabled
		// or if the lens hasn't been used.
		const canBlend = lens.blendEnabledLayersOnTransition !== false || lens.lastEnabledLayers == null;

		// Disable any layer not active or allowed
		for (const layerType of this.enabledLayers) {
			const layer = this.layers.get(layerType);
			if (layer == undefined) {
				console.error(`lens-manager: Failed to find '${layerType}' while trying to disable inactive layers`);
				continue;
			}

			if (!nextLensLayers.has(layerType) && (!canBlend || !nextAllowedLayers.has(layerType))) {
				this.disableLayer(layerType);
			}
		}

		this.enableLayers(nextLensLayers);
		const hasLegend = lens?.hasLegend ?? false;
		window.dispatchEvent(new LensActivationEvent(prevLensString, this.activeLens, hasLegend));

		return true;
	}

	getActiveLayers(lens: ILens): Set<keyof LensLayerTypeMap> {
		const activeLayers = lens.activeLayers;

		if (lens.useUserConfig) {
			for (const layer of this.layers) {
				const layerName = layer[0];
				const optionID = this.getLayerOption(layerName);
				if (optionID != layerName) {
					const shouldEnable = UI.getOption("user", "GamePlay", optionID) == 1;
					if (shouldEnable && !activeLayers.has(layerName)) {
						activeLayers.add(layerName);
					} else if (!shouldEnable && activeLayers.has(layerName)) {
						activeLayers.delete(layerName);
					}
				}
			}
		}

		return activeLayers;
	}

	enableLayers(layerTypes: Set<LensLayerName>) {
		for (const layerType of layerTypes) {
			this.enableLayer(layerType);
		}
	}

	enableLayer(layerType: LensLayerName): boolean {
		const layer: ILensLayer | undefined = this.layers.get(layerType);
		if (layer == undefined) {
			console.error(`lens-manager: enableLayer failed to find lens layer for type '${layerType}'`);
			return false;
		}

		if (this.enabledLayers.has(layerType)) {
			if (this.showDebugInfo) {
				console.info(`lens-manager: Lens layer '${layerType}' is already enabled!`);
			}
			return false;
		}

		if (this.showDebugInfo) {
			console.info(`lens-manager: Enabling '${layerType}' layer`);
		}

		this.enabledLayers.add(layerType);
		layer.applyLayer();
		this.writeEnabledLayers();
		window.dispatchEvent(new LensLayerEvent(LensLayerEnabledEventName, layerType));

		return true;
	}

	disableLayer(layerType: LensLayerName): boolean {
		const layer: ILensLayer | undefined = this.layers.get(layerType);
		if (layer == undefined) {
			console.error(`lens-manager: disableLayer failed to find lens layer for type '${layerType}'`);
			return false;
		}

		if (this.enabledLayers.has(layerType) == false) {
			if (this.showDebugInfo) {
				console.warn(`lens-manager: Lens layer '${layerType}' is already disabled!`);
			}
			return false;
		}

		if (this.showDebugInfo) {
			console.info(`lens-manager: Disabling '${layerType}' layer`);
		}

		this.enabledLayers.delete(layerType);
		layer.removeLayer();
		this.writeEnabledLayers();
		window.dispatchEvent(new LensLayerEvent(LensLayerDisabledEventName, layerType));

		return true;
	}

	getLayerOption(layerType: LensLayerName): string {
		const layer: ILensLayer | undefined = this.layers.get(layerType);
		if (layer == undefined) {
			console.error(`lens-manager: enableLayer failed to find lens layer for type '${layerType}'`);
			return "";
		}

		if (typeof layer.getOptionName !== "undefined") {
			return layer.getOptionName();
		}

		// if the layer doesn't define an option name, just return its type to maintain the old behavior
		return layerType;
	}

	/**
	 * toggleLayer toggles a layer on or off
	 *
	 * @param layerType The name of layer to toggle
	 * @param force If true, forces the layer to be enabled. If false, forces the layer to be disabled. If undefined, toggles the layer.
	 *
	 * @returns true if the layer was toggled, false if the layer was already in the desired state
	 */
	toggleLayer(layerType: LensLayerName, options?: LensToggleOptions): boolean {
		const layer: ILensLayer | undefined = this.layers.get(layerType);
		if (layer == undefined) {
			console.error(`lens-manager: toggleLayer failed to find lens layer for type '${layerType}'`);
			return false;
		}

		// Pull out options and current state.
		const force: boolean | undefined = options?.force; // Force enabled/disabled (if set)
		const serialize = options?.serialize === true; // Write out to disk?
		const isEnabled = this.enabledLayers.has(layerType); // Is layer currently enabled?

		const enable = force ?? !isEnabled;
		let successful = true;
		if (enable) {
			successful = this.enableLayer(layerType);
		} else {
			successful = this.disableLayer(layerType);
		}

		// If previous operations were sucessful, and serializng out to User config
		if (successful && serialize === true) {
			// Does this have an entry in the user configuration (if it resolved to itself, it doesn't).
			const id = LensManager.getLayerOption(layerType); // Find key in config. e.g., fxs-hexgrid-layer = "ShowMapGrid"
			if (id != layerType) {
				this.writeTrackedLayer(id, enable);
			}
		}

		return successful;
	}

	isLayerEnabled(layerType: LensLayerName): boolean {
		const layer: ILensLayer | undefined = this.layers.get(layerType);
		if (layer == undefined) {
			console.error(`lens-manager: isLayerEnabled failed to find lens layer for type '${layerType}'`);
			return false;
		}
		return this.enabledLayers.has(layerType);
	}

	/**
	 * Returns the serialized state of the lens layer, if one exists.
	 * @param layerType Name of the layer to look up.
	 * @returns true if set to enabled, false if disabled, or undefined if no entry.
	 */
	private getSerializedState(layerType: LensLayerName): boolean | undefined {
		const id = LensManager.getLayerOption(layerType); // Find key in config. e.g., fxs-hexgrid-layer = "ShowMapGrid"
		if (id != layerType) {
			return this.readTrackedLayer(id);
		}
		return undefined;
	}

	private readTrackedLayer(layerID: string): boolean {
		if (Configuration.getGame().isHotseat) {
			const obj = this.currentCatalog.getObject(LENS_CATALOG_OBJECT_NAME);
			const value = !!obj.read(layerID);
			return value;
		}
		return UI.getOption("user", "GamePlay", layerID) == 1;
	}

	private writeTrackedLayer(layerID: string, enable: boolean) {
		if (Configuration.getGame().isHotseat) {
			const obj = this.currentCatalog.getObject(LENS_CATALOG_OBJECT_NAME);
			obj.write(layerID, enable);
		} else {
			UI.setOption("user", "GamePlay", layerID, enable ? 1 : 0);
			Configuration.getUser().saveCheckpoint();
		}
	}

	private writeEnabledLayers() {
		if (!this.activeLens) {
			return;
		}

		const obj = this.currentCatalog.getObject(this.activeLens);
		const enabledLayers = Array.from(this.enabledLayers);
		if (enabledLayers && enabledLayers.length > 0) {
			obj.write(ENABLED_LAYERS_CATALOG_OBJECT_ID, enabledLayers.join(":"));
		} else {
			obj.write(ENABLED_LAYERS_CATALOG_OBJECT_ID, "");
		}
	}

	private getEnabledLayers(): Set<LensLayerName> | undefined {
		if (!this.activeLens) {
			return;
		}

		const obj = this.currentCatalog.getObject(this.activeLens);
		const enabledLayers = obj.read(ENABLED_LAYERS_CATALOG_OBJECT_ID);
		const enabledLayersString = String(enabledLayers);
		if (enabledLayers && enabledLayersString.length > 0) {
			const array = enabledLayersString.split(":") as LensLayerName[];
			return new Set(array);
		} else {
			return undefined;
		}
	}

	private resetLayersFromSerialize() {
		// Update active layers from catalog
		this.layers.forEach((_layer, layerType) => {
			const isLayerEnabled: boolean = LensManager.getSerializedState(layerType) === true;
			if (isLayerEnabled) {
				this.enableLayer(layerType);
			} else {
				this.disableLayer(layerType);
			}
		});
	}

	private onLocalPlayerChanged() {
		this.playerID = GameContext.localPlayerID;

		// if the catalog doesn't exist for this player, create a new one.
		if (this.catalogs[this.playerID] == undefined) {
			this.currentCatalog = new Catalog({
				name: LENS_CATALOG_NAME,
				version: LENS_CATALOG_VERSION,
				player: Players.get(this.playerID),
			});
			this.catalogs[this.playerID] = this.currentCatalog;
		} else {
			this.currentCatalog = this.catalogs[this.playerID];
		}

		this.resetLayersFromSerialize();
	}
}

const LensManager = new LensManagerSingleton();
export default LensManager;
